update products set tagline='The quiet before the light returns.',description='All black, with the crescent barely there. Black case, black strap, an embossed graphite dial with a silver crescent. Japanese quartz.',long_description='All black, with the crescent barely there. It is the new moon, when nothing is shown and everything is promised. A black tonneau case, 44 × 52 mm and 17 mm deep, with a deep and even finish. The black silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Soma New Moon belongs to Soma, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.',features='["Embossed graphite dial with a silver crescent", "Japanese quartz movement", "Black tonneau case, Black silicone strap", "44 × 52 mm, 17 mm deep", "1-year warranty"]'::jsonb,specs='{"Movement": "Japanese quartz", "Case": "Black, tonneau, 44 × 52 mm, 17 mm deep", "Strap": "Black silicone", "Dial": "Embossed graphite dial", "Weight": "Approx. 85 g", "Warranty": "1 year"}'::jsonb,seo_title='Soma New Moon · Soma Collection | YUGASTRA',seo_description='The quiet before the light returns. Soma New Moon: black case, black strap, an embossed graphite dial with a silver crescent. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.' where slug='soma-new-moon';
update products set tagline='Moonlight, in monochrome.',description='A black case set off by a white strap. Black case, white strap, an embossed graphite dial with a silver crescent. Japanese quartz.',long_description='A black case set off by a white strap. Stark and graceful, like a moonlit path in a still garden. A black tonneau case, 44 × 52 mm and 17 mm deep, with a deep and even finish. The white silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Soma Moonlight belongs to Soma, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.',features='["Embossed graphite dial with a silver crescent", "Japanese quartz movement", "Black tonneau case, White silicone strap", "44 × 52 mm, 17 mm deep", "1-year warranty"]'::jsonb,specs='{"Movement": "Japanese quartz", "Case": "Black, tonneau, 44 × 52 mm, 17 mm deep", "Strap": "White silicone", "Dial": "Embossed graphite dial", "Weight": "Approx. 85 g", "Warranty": "1 year"}'::jsonb,seo_title='Soma Moonlight · Soma Collection | YUGASTRA',seo_description='Moonlight, in monochrome. Soma Moonlight: black case, white strap, an embossed graphite dial with a silver crescent. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.' where slug='soma-moonlight';
